from models import Job

class RetryPolicy:
    """Pure policy: decide; do not mutate the job."""
    def can_attempt(self, job: Job, now: float) -> bool:
        return job.status not in {"succeeded", "failed", "timed_out"} and job.attempts < job.max_attempts and now <= job.deadline

    def after_error(self, job: Job, retryable: bool, now: float) -> str:
        if now > job.deadline:
            return "timed_out"
        if retryable and job.attempts < job.max_attempts:
            return "pending"
        return "failed"

