from copy import deepcopy
from models import Job

class JobStore:
    """Small transactional boundary used by the worker.

    A delivery is committed with the resulting job snapshot. Redelivery must
    return the already committed snapshot and must not execute user work again.
    """
    def __init__(self) -> None:
        self._jobs: dict[str, Job] = {}
        self._deliveries: dict[str, Job] = {}

    def add(self, job: Job) -> None:
        if job.id in self._jobs:
            raise ValueError(f"duplicate job {job.id}")
        self._jobs[job.id] = deepcopy(job)

    def get(self, job_id: str) -> Job:
        if job_id not in self._jobs:
            raise KeyError(job_id)
        return deepcopy(self._jobs[job_id])

    def save(self, job: Job) -> None:
        if job.id not in self._jobs:
            raise KeyError(job.id)
        self._jobs[job.id] = deepcopy(job)

    def committed(self, event_id: str) -> Job | None:
        # BUG: redelivery state was never persisted.
        return None

    def commit_delivery(self, event_id: str, job: Job) -> None:
        # BUG: saving the job and delivery marker must form one logical commit.
        self.save(job)

    def snapshot(self) -> dict[str, Job]:
        return deepcopy(self._jobs)

