from collections.abc import Callable, Iterable
from models import Delivery, Execution, Job
from worker import Worker

class DeliveryService:
    def __init__(self, worker: Worker, executor: Callable[[dict], Execution]) -> None:
        self.worker = worker
        self.executor = executor

    def drain(self, deliveries: Iterable[Delivery]) -> list[Job]:
        results = []
        for delivery in deliveries:
            results.append(self.worker.handle(delivery, self.executor))
        return results

