from collections import Counter
from models import Job, TERMINAL


def validate_history(job: Job) -> list[str]:
    """Return invariant violations without mutating the captured job."""
    problems: list[str] = []
    attempts = [event for event in job.history if event.get("event") == "attempt_started"]
    if len(attempts) != job.attempts:
        problems.append("attempt counter does not match attempt_started history")
    if job.attempts > job.max_attempts:
        problems.append("attempt budget exceeded")
    if job.status in TERMINAL and not job.history:
        problems.append("terminal job has no transition history")
    times = [event.get("at") for event in job.history]
    if any(not isinstance(at, (int, float)) for at in times):
        problems.append("history contains an invalid timestamp")
    if times != sorted(times):
        problems.append("history timestamps move backwards")
    return problems


def transition_counts(job: Job) -> dict[str, int]:
    return dict(Counter(str(event.get("event")) for event in job.history))


def summary(job: Job) -> dict[str, object]:
    """Stable diagnostic payload suitable for a log or test assertion."""
    return {
        "job_id": job.id,
        "status": job.status,
        "attempts": job.attempts,
        "max_attempts": job.max_attempts,
        "deadline": job.deadline,
        "result_present": job.result is not None,
        "error": job.error,
        "transitions": transition_counts(job),
        "violations": validate_history(job),
    }


def latest_transition(job: Job) -> str | None:
    """Return the final transition name for concise incident summaries."""
    if not job.history:
        return None
    return str(job.history[-1].get("event"))


def is_consistent(job: Job) -> bool:
    """Expose invariant validation as a boolean health signal."""
    return not validate_history(job)

