from collections.abc import Callable, Iterable
from models import Delivery, Execution, Job
from service import DeliveryService


def ordered(deliveries: Iterable[Delivery]) -> list[Delivery]:
    """Provide a deterministic replay order for a captured delivery batch."""
    return sorted(deliveries, key=lambda item: (item.delivered_at, item.event_id))


def replay(service: DeliveryService, deliveries: Iterable[Delivery]) -> list[Job]:
    """Replay captured messages; idempotency remains the worker's responsibility."""
    return service.drain(ordered(deliveries))


def scripted_executor(outcomes: Iterable[Execution]) -> Callable[[dict], Execution]:
    """Build a deterministic executor for reproducing retry sequences."""
    remaining = iter(outcomes)
    def execute(_payload: dict) -> Execution:
        try:
            return next(remaining)
        except StopIteration as error:
            raise AssertionError("executor called more often than the script allows") from error
    return execute


def terminal_states(jobs: Iterable[Job]) -> dict[str, str]:
    """Return each job's latest observed state in a replay."""
    states: dict[str, str] = {}
    for job in jobs:
        states[job.id] = job.status
    return states


def attempts_by_job(jobs: Iterable[Job]) -> dict[str, int]:
    attempts: dict[str, int] = {}
    for job in jobs:
        attempts[job.id] = max(attempts.get(job.id, 0), job.attempts)
    return attempts

