import math
from cache import KVCache, Vector


def dot(a: Vector,b: Vector)->float:
    if len(a)!=len(b): raise ValueError("dimension mismatch")
    return sum(x*y for x,y in zip(a,b))


def softmax(values:list[float])->list[float]:
    # TODO: implement a numerically stable softmax.
    total=sum(math.exp(x) for x in values)
    return [math.exp(x)/total for x in values]


def attend(query:Vector,keys:list[Vector],values:list[Vector])->Vector:
    if not keys or len(keys)!=len(values): raise ValueError("aligned non-empty K/V required")
    scale=math.sqrt(len(query))
    weights=softmax([dot(query,key)/scale for key in keys])
    return [sum(weight*value[d] for weight,value in zip(weights,values)) for d in range(len(values[0]))]


def cached_step(cache:KVCache,position:int,query:Vector,key:Vector,value:Vector)->Vector:
    """Append the token, then compute causal attention over the retained window."""
    cache.append(position,key,value)
    keys,values=cache.visible(position)
    return attend(query,keys,values)

