import math,unittest
from attention import attend,cached_step,softmax
from cache import KVCache

class KVCacheTests(unittest.TestCase):
    def assertClose(self,a,b,tol=1e-9):
        self.assertEqual(len(a),len(b));self.assertTrue(all(abs(x-y)<=tol for x,y in zip(a,b)),(a,b))

    def test_softmax_is_stable_and_normalized(self):
        got=softmax([1000.0,1001.0,999.0])
        self.assertTrue(all(math.isfinite(x) for x in got));self.assertAlmostEqual(sum(got),1);self.assertGreater(got[1],got[0]);self.assertGreater(got[0],got[2])

    def test_cache_requires_contiguous_absolute_positions(self):
        cache=KVCache(3);cache.append(7,[1.0],[2.0])
        with self.assertRaises(ValueError):cache.append(9,[1.0],[2.0])

    def test_window_evicts_oldest_and_tracks_absolute_start(self):
        cache=KVCache(2)
        for position in range(3):cache.append(position,[float(position)],[float(position+10)])
        self.assertEqual((cache.start_position,cache.keys),(1,[[1.0],[2.0]]))
        self.assertEqual(cache.visible(2),([[1.0],[2.0]],[[11.0],[12.0]]))

    def test_cached_steps_match_explicit_sliding_window_attention(self):
        cache=KVCache(3);keys=[];values=[]
        for position in range(6):
            query=[position+0.5,1.0];key=[position*0.25,1.0];value=[float(position),float(position*position)]
            keys.append(key);values.append(value)
            self.assertClose(cached_step(cache,position,query,key,value),attend(query,keys[-3:],values[-3:]))

    def test_dimension_and_configuration_errors_are_explicit(self):
        with self.assertRaises(ValueError):KVCache(0)
        with self.assertRaises(ValueError):attend([1.0],[[1.0,2.0]],[[3.0]])

if __name__=='__main__':unittest.main()

import unittest
from experiment import mean_ci95,paired_differences,regression_decision

class ExperimentTests(unittest.TestCase):
    def test_paired_contract_and_estimate(self):
        self.assertEqual(paired_differences([10,20,30],[12,19,35]),[2,-1,5])
        with self.assertRaises(ValueError):paired_differences([1],[2])
        with self.assertRaises(ValueError):paired_differences([1,2],[2])

    def test_ci_uses_standard_error(self):
        estimate,low,high=mean_ci95([1.0,2.0,3.0,4.0])
        self.assertEqual(estimate,2.5);self.assertAlmostEqual(low,1.2348254402389105);self.assertAlmostEqual(high,3.7651745597610895)

    def test_ship_requires_entire_interval_above_practical_threshold(self):
        decision=regression_decision([10,10,10,10],[13,13,13,13],min_effect=2)
        self.assertEqual(decision.action,'ship');self.assertGreaterEqual(decision.low,2);self.assertIn('interval',decision.reason)

    def test_reject_requires_entire_interval_below_zero(self):
        decision=regression_decision([10,10,10,10],[8,8,8,8],min_effect=1)
        self.assertEqual(decision.action,'reject');self.assertLess(decision.high,0)

    def test_uncertain_or_too_small_result_collects_more_data(self):
        noisy=regression_decision([10,10,10,10],[8,14,9,13],min_effect=1)
        small=regression_decision([10,10,10,10],[10.5,10.5,10.5,10.5],min_effect=1)
        self.assertEqual(noisy.action,'collect-more');self.assertEqual(small.action,'collect-more')

if __name__=='__main__':unittest.main()
